-- ts-design-studio 0.12.0 – připomínky klienta k nahranému návrhu (MySQL)
CREATE TABLE IF NOT EXISTS studio_feedback (id INT AUTO_INCREMENT PRIMARY KEY, project_id INT NOT NULL, num INT NOT NULL, delivery_id INT NOT NULL, kind VARCHAR(10) NOT NULL, author VARCHAR(120) NOT NULL DEFAULT '', section VARCHAR(80) NOT NULL DEFAULT '', body TEXT NOT NULL, status VARCHAR(8) NOT NULL DEFAULT 'new', notified_at VARCHAR(19) NOT NULL DEFAULT '', synced_at VARCHAR(19) NOT NULL DEFAULT '', done_by INT NOT NULL DEFAULT 0, done_at VARCHAR(19) NOT NULL DEFAULT '', created_at VARCHAR(19) NOT NULL, KEY studio_feedback_project (project_id, id), KEY studio_feedback_delivery (delivery_id, id)) DEFAULT CHARSET=utf8mb4;
